/**
 * Sous-thème « Valorant » (thème GAMING) — données pures, AUCUN import (partagé avec convex/cardsCatalog.ts).
 *
 * Source : spec BDD du côté données (02/11/2026) + `Tri-etoiles-valorant.xlsx` (colonne « Étoiles finales (VALIDÉ) »).
 * 995 cartes = 30 agents + 789 skins d'armes + 176 couteaux (tiers Deluxe et au-dessus, sans chromas ni Standard).
 * Noms officiels FR (valorant-api.com, fr-FR). Répartition : 308 × 1★ · 236 × 2★ · 205 × 3★ · 113 × 4★ · 92 × 5★ · 41 × 6★.
 *
 * Illustrations : public/art/valorant/<uuid>.png, téléchargées une fois (scripts/make-valorant.py), jamais en hotlink.
 * Agents : portrait en pied (fullPortrait). Armes très larges : pivotées en diagonale (canon vers le haut) pour remplir
 * une carte en portrait. Ordre des numéros : agents (A→Z), puis skins regroupés par collection (pistolets → fusils →
 * mêlée), pour que la collection se lise par ensemble.
 * Identifiant de carte = `val-<uuid Riot>` : stable même si un nom change.
 */
export type ValorantRarity = 'common' | 'uncommon' | 'rare' | 'epic' | 'legendary' | 'mythic';
export type ValorantKind = 'agent' | 'skin' | 'knife';

export interface ValorantEntry {
  /** numéro de carte (1..995) */
  num: number;
  /** uuid valorant-api (skin ou agent) */
  uuid: string;
  /** nom FR officiel, ex. « Vandal (Feu ancien) », « Jett » */
  name: string;
  rarity: ValorantRarity;
  kind: ValorantKind;
  /** arme (« Vandal », « Mêlée »…) ou rôle pour un agent (« Duelliste »…) */
  weapon: string;
  /** collection du skin (« Feu ancien »…) — vide pour un agent */
  collection: string;
  /** tier Riot : Deluxe | Premium | Exclusive | Ultra | Agent */
  tier: string;
}

export const VALORANT_INFO = { id: 'valorant', label: 'Valorant', code: 'VAL', size: 995, artDir: 'art/valorant' } as const;

